    DASHBOARD_URL: "https://your-dashboard-url/",      // linked at the bottom of every email/card
    EMAIL_TO: "tharakajce.97@gmail.com",                       // comma-separated list for the team digest
    EMAIL_FROM: "Threat Intel <tharakajce.97@gmail.com>",        // must match the SMTP credential account

    // Vendors/products in client environments. Case-insensitive substring match on
    // vendorProject + product (KEV) and title + summary (news).
    VENDOR_ALLOWLIST: [
      "Microsoft","Windows","Exchange","SharePoint","Office","Entra","Azure","Intune",
      "Fortinet","FortiGate","FortiOS","FortiManager","FortiAnalyzer","FortiClient",
      "ConnectWise","ScreenConnect","NinjaOne","Ninja RMM",
      "Cisco","Ivanti","Citrix","NetScaler","VMware","Broadcom","Veeam","SonicWall",
      "Palo Alto","PAN-OS","GlobalProtect","Apple","iOS","macOS","Google","Chrome","Chromium",
      "Mozilla","Firefox","Adobe","Acrobat","Atlassian","Confluence","Jira","Oracle",
      "SolarWinds","Zoho","ManageEngine","Synology","QNAP","Ubiquiti","UniFi",
      "Dell","Lenovo","Progress","MOVEit","GitLab","Jenkins","OpenSSL","Linux","Ubuntu",
      "Samba","PaperCut","Kaseya","CrowdStrike","Proofpoint","ThreatLocker","7-Zip","WinRAR",
      "Auvik","Proxmox","Hyper-V","SQL Server","Teams","OneDrive","Outlook","Defender"
    ],

    // High-signal phrases for news scoring (weight added to score)
    SIGNAL_TERMS: {
      "zero-day": 3, "0-day": 3, "actively exploited": 3, "in the wild": 3,
      "exploited": 2, "ransomware": 2, "critical": 1, "rce": 2, "remote code execution": 2,
      "authentication bypass": 2, "patch now": 2, "emergency": 2, "out-of-band": 2,
      "cve-": 1, "australia": 2, "australian": 2, "msp": 2, "mssp": 2, "rmm": 2,
      "supply chain": 1, "phishing": 1, "data breach": 1
    },
    MIN_SCORE: 3,                 // article is "relevant" at or above this
    NEWS_MAX_AGE_DAYS: 7,         // ignore feed items older than this (MSRC feed returns its whole history)
    KEV_LOOKBACK_DAYS: 14,        // on first run, only notify about KEV entries this recent
    AI_ENABLED: false,            // flip to true once ANTHROPIC key is set in the AI node

    // CVE Watch / enrichment (TI 04, TI 05)
    NVD_API_KEY: "YOUR-NVD-API-KEY",   // https://nvd.nist.gov/developers/request-an-api-key
    CVSS_MIN: 7.0,                     // CVE Watch keeps CVEs at or above this base score
    CVE_LOOKBACK_HOURS: 48,            // NVD publication window per run
    ENRICH_BATCH: 60                   // KEV rows enriched per TI 05 run
  }
}];

const pickCvss = (metrics) => {
  const order = [['cvssMetricV40','4.0'],['cvssMetricV31','3.1'],['cvssMetricV30','3.0'],['cvssMetricV2','2.0']];
  for (const [key, ver] of order) {
    const arr = metrics?.[key];
    if (Array.isArray(arr) && arr.length) {
      const m = arr.find(x => x.type === 'Primary') || arr[0];
      const d = m.cvssData || {};
      const score = d.baseScore;
      let sev = d.baseSeverity || m.baseSeverity;
      if (!sev && typeof score === 'number') sev = score >= 9 ? 'CRITICAL' : score >= 7 ? 'HIGH' : score >= 4 ? 'MEDIUM' : 'LOW';
      return { score, severity: sev ? String(sev).toUpperCase() : null, vector: d.vectorString || null, version: ver };
    }
  }
  return { score: null, severity: null, vector: null, version: null };
};
const cpeParts = (configurations) => {
  const vendors = new Set(), products = new Set();
  for (const c of configurations || []) for (const n of c.nodes || []) for (const m of n.cpeMatch || []) {
    const p = String(m.criteria || '').split(':');
    if (p.length > 4) { vendors.add(p[3]); products.add(p[4]); }
  }
  return { vendors: [...vendors], products: [...products] };
};
const chunk = (arr, n) => { const out = []; for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n)); return out; };

const wanted = $('Get unenriched KEV').all().map(i => i.json.cve_id);
const byId = {};
for (const item of $input.all()) {
  const j = item.json || {};
  const v = (j.vulnerabilities || [])[0]?.cve;
  if (v?.id) byId[v.id] = pickCvss(v.metrics);
}
const rows = wanted.map(id => {
  const cv = byId[id] || { score: null, severity: null, vector: null, version: null };
  return { cve_id: id, cvss_score: cv.score, cvss_severity: cv.severity, cvss_vector: cv.vector, cvss_version: cv.version };
});
return [{ json: { rows, ids: wanted, nvd_found: Object.keys(byId).length } }];

const ids = $input.first().json.ids || [];
const chunk = (arr, n) => { const out = []; for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n)); return out; };
return chunk(ids, 100).map(c => ({ json: { cves: c.join(',') } }));

const rows = $('Parse NVD').first().json.rows;
const epss = {};
for (const item of $input.all()) {
  for (const d of (item.json?.data || [])) epss[d.cve] = { epss: Number(d.epss), percentile: Number(d.percentile) };
}
for (const r of rows) {
  const e = epss[r.cve_id];
  r.epss_score = e ? e.epss : null;
  r.epss_percentile = e ? e.percentile : null;
}
return [{ json: { rows, ids: rows.map(r => r.cve_id), epss_found: Object.keys(epss).length } }];

const rows = $('Merge EPSS').first().json.rows;
const now = new Date().toISOString();
for (const r of rows) r.enriched_at = now;
return [{ json: { rows, count: rows.length } }];
